def muted_to_notify_level(apps, schema_editor):
    ConversationMember = apps.get_model("db", "ConversationMember")
    ConversationMember.objects.filter(is_muted=True).update(notify_level="off")
    ConversationMember.objects.filter(is_muted=False, conversation__type="group").update(notify_level="mentions")
    ConversationMember.objects.filter(is_muted=False, conversation__type="direct").update(notify_level="all")


def notify_level_to_muted(apps, schema_editor):
    ConversationMember = apps.get_model("db", "ConversationMember")
    ConversationMember.objects.filter(notify_level="off").update(is_muted=True)


